package ai.eva.android.probe;
import org.json.*;import java.io.*;import java.util.*;import java.security.MessageDigest;
/** Edits only Android-created user declarations. Trust remains a separate kernel action. */
final class HookStore {
 static final String[] EVENTS={"PreToolUse","PermissionRequest","PostToolUse","PreCompact","PostCompact","SessionStart","UserPromptSubmit","SubagentStart","SubagentStop","Stop","Interrupt"};
 static void validate(String event,String command,String matcher,int timeout)throws IOException{if(!Arrays.asList(EVENTS).contains(event))throw new IOException("不支持的事件");if(command.trim().isEmpty()||command.length()>8192||command.indexOf(0)>=0)throw new IOException("命令为空、过长或包含空字符");if(matcher.length()>512||matcher.indexOf(0)>=0||matcher.contains("\n"))throw new IOException("匹配条件无效");if(timeout<1||timeout>300)throw new IOException("超时须在 1–300 秒之间");}
 static String canonical(Object value)throws Exception{if(value instanceof JSONObject){JSONObject object=(JSONObject)value;TreeSet<String> keys=new TreeSet<>();Iterator<String> iterator=object.keys();while(iterator.hasNext())keys.add(iterator.next());StringBuilder out=new StringBuilder("{");for(String key:keys){if(out.length()>1)out.append(",");out.append(JSONObject.quote(key)).append(":").append(canonical(object.get(key)));}return out.append("}").toString();}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int i=0;i<array.length();i++){if(i>0)out.append(",");out.append(canonical(array.get(i)));}return out.append("]").toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
 static String hash(JSONObject object)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(canonical(object).getBytes("UTF-8"));StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b&255));return s.toString();}
 static JSONObject userLayer(KernelHost host)throws Exception{JSONObject read=host.rpc("config/read",new JSONObject().put("includeLayers",true));JSONArray layers=read.optJSONArray("layers");if(layers!=null)for(int i=0;i<layers.length();i++){JSONObject layer=layers.getJSONObject(i),name=layer.optJSONObject("name");if(name!=null&&name.optString("type").equals("user")&&name.optString("file").equals("/root/.eva-codex/config.toml")&&(name.isNull("profile")||name.optString("profile").isEmpty()))return layer;}throw new IOException("内核未返回用户配置层，未修改任何文件");}
 static synchronized JSONObject call(KernelHost host,JSONObject args)throws Exception{
  JSONObject layer=userLayer(host),config=layer.getJSONObject("config"),hooks=config.optJSONObject("hooks");if(hooks==null)hooks=new JSONObject();String version=layer.getString("version"),action=args.optString("action","list");android.content.SharedPreferences preferences=host.context.getSharedPreferences("eva-hook-ownership",0);JSONObject owned=new JSONObject(preferences.getString("entries","{}"));
  if(action.equals("list")){JSONArray entries=new JSONArray();Iterator<String> ids=owned.keys();while(ids.hasNext()){String id=ids.next();JSONObject info=owned.getJSONObject(id);JSONArray groups=hooks.optJSONArray(info.getString("event"));int index=info.getInt("index");JSONObject group=groups==null?null:groups.optJSONObject(index);if(group==null||!hash(group).equals(info.getString("hash")))continue;JSONArray handlers=group.optJSONArray("hooks");if(handlers==null||handlers.length()!=1)continue;JSONObject handler=handlers.getJSONObject(0);entries.put(new JSONObject().put("id",id).put("event",info.getString("event")).put("command",handler.optString("command")).put("matcher",group.optString("matcher")).put("timeout",handler.optInt("timeout",10)));}return new JSONObject().put("revision",version).put("entries",entries).put("events",new JSONArray(Arrays.asList(EVENTS)));}
  if(!version.equals(args.optString("revision")))throw new IOException("配置已改变，请刷新后重新编辑；草稿未保存");String id=args.optString("id"),event=args.optString("event");JSONObject info=id.isEmpty()?null:owned.optJSONObject(id);if(!id.isEmpty()&&info==null)throw new IOException("只能修改手机创建的钩子");if(info!=null)event=info.getString("event");if(!Arrays.asList(EVENTS).contains(event))throw new IOException("不支持的事件");JSONArray groups=hooks.optJSONArray(event);if(groups==null)groups=new JSONArray();int index=info==null?groups.length():info.getInt("index");if(info!=null){JSONObject old=groups.optJSONObject(index);if(old==null||!hash(old).equals(info.getString("hash")))throw new IOException("钩子已被其他工具修改，未覆盖");}
  JSONObject group;
  if(action.equals("delete")){if(info==null)throw new IOException("钩子不存在");group=new JSONObject().put("hooks",new JSONArray());owned.remove(id);}
  else if(action.equals("save")){String command=args.getString("command"),matcher=args.optString("matcher");int timeout=args.getInt("timeout");validate(event,command,matcher,timeout);group=new JSONObject().put("hooks",new JSONArray().put(new JSONObject().put("type","command").put("command",command).put("timeout",timeout)));if(!matcher.isEmpty())group.put("matcher",matcher);if(id.isEmpty())id=UUID.randomUUID().toString();owned.put(id,new JSONObject().put("event",event).put("index",index).put("hash",hash(group)));}
  else throw new IOException("未知钩子操作");groups.put(index,group);
  // Keep empty matcher groups on deletion: other groups' trust keys contain indices.
  JSONObject result=host.rpc("config/value/write",new JSONObject().put("keyPath","hooks."+event).put("value",groups).put("mergeStrategy","replace").put("filePath","/root/.eva-codex/config.toml").put("expectedVersion",version));if(!preferences.edit().putString("entries",owned.toString()).commit())throw new IOException("钩子已写入，但管理索引保存失败，请刷新核对");return new JSONObject().put("saved",true).put("status",result.optString("status")).put("instruction","已保存声明，未自动信任。请在列表检查命令与指纹，再决定是否信任。");
 }
}
